package zw.ac.uz.dpdms.alert; import java.time.*; import java.util.*; import org.springframework.scheduling.annotation.Async; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/alerts") public class AlertController{private final AlertRepository logs;public AlertController(AlertRepository l){logs=l;} @GetMapping public List<AlertLog> all(){return logs.findAll();} @PostMapping public AlertLog queue(@RequestBody AlertLog a){a.id=null;a.deliveryStatus="QUEUED";a.createdAt=Instant.now();AlertLog saved=logs.save(a);deliver(saved.id);return saved;} @Async void deliver(Long id){logs.findById(id).ifPresent(a->{a.deliveryStatus="SIMULATED_DELIVERED";a.deliveredAt=Instant.now();logs.save(a);});}}
